import {s,connect,eligible,message} from './accounts.mjs';
export async function initFirebaseLicense(){
let b=null,account=null,stop=null,error='',generation=0;
// This account edition requires a live server check before editing. Inventory stays local.
const access={storageKey:'milai-click-v1',business:null,countId:null,season:null};globalThis.milaiAccess=access;
const live=()=>navigator.onLine&&eligible(account);
access.canWrite=session=>live()&&!session?.completedAt;access.canStart=live;access.acquire=async()=>live();access.finish=async session=>{if(!session.completedAt&&!live())throw Error('החשבון אינו פעיל');return session.completedAt||Date.now()};
const bar=document.createElement('section');bar.className='activation-bar';const label=document.createElement('span'),open=document.createElement('button');open.textContent='החשבון שלי';bar.append(label,open);document.querySelector('main').prepend(bar);
const dialog=document.createElement('dialog');dialog.innerHTML='<button type="button" class="close">×</button><h2>החשבון שלי</h2><p class="status" role="status"></p><form><label>אימייל<input name="email" type="email" dir="ltr" autocomplete="username" required></label><label>סיסמה<input name="password" type="password" minlength="12" autocomplete="current-password" required></label><details><summary>לקוח חדש — פרטי העסק להרשמה</summary><label>שם עסק<input name="businessName" maxlength="100"></label><label>עוסק / ח.פ.<input name="number" maxlength="24"></label></details><button class="primary" name="action" value="login">כניסה</button><button type="submit" name="action" value="register">הרשמה</button><button type="button" class="reset">איפוס סיסמה</button></form><button class="refresh" type="button">רענון מצב</button><button class="logout" type="button">התנתקות</button><p>אחרי הרשמה, המנהל פותח את החשבון לאחר בדיקת התשלום. מוצרים וכמויות נשמרים במכשיר. נדרש אינטרנט לצורך ספירה; ללא חיבור אפשר לצפות, לגבות ולייצא.</p>';document.body.append(dialog);
const status=dialog.querySelector('.status'),form=dialog.querySelector('form');
function paint(){const active=live();access.business=account?{name:account.businessName,number:account.number}:null;const text=active?'החשבון פעיל עד '+new Date(account.expiresAt).toLocaleString('he-IL'):!navigator.onLine?'אין חיבור — צפייה וגיבוי זמינים':account?.status==='blocked'?'החשבון חסום — פנה למנהל':account?.status==='pending'?'החשבון ממתין לפתיחה לאחר תשלום':account?.status==='active'?'תוקף החשבון הסתיים':b?.auth.currentUser?'כרטיס העסק טרם נוצר. מלא פרטי עסק ולחץ הרשמה':'יש להתחבר לחשבון';label.textContent=text;status.textContent=error||text;bar.dataset.active=String(active);dialog.querySelector('.logout').hidden=!b?.auth.currentUser;document.dispatchEvent(new CustomEvent('milai-license-change'))}
async function ensure(){if(!b)b=await connect();return b}
async function refresh(){const id=++generation;try{await ensure();if(!b.auth.currentUser){account=null;paint();return}const snap=await s.getDocFromServer(s.doc(b.db,'customerAccounts',b.auth.currentUser.uid));if(id!==generation)return;account=snap.exists()?snap.data():null;error='';paint()}catch(e){if(id!==generation)return;account=null;error=message(e);paint()}}
async function listen(){stop?.();await ensure();if(!b.auth.currentUser)return;stop=s.onSnapshot(s.doc(b.db,'customerAccounts',b.auth.currentUser.uid),{includeMetadataChanges:true},snap=>{generation++;account=!snap.metadata.fromCache&&snap.exists()?snap.data():null;error='';paint()},e=>{generation++;account=null;error=message(e);paint()})}
form.onsubmit=async event=>{event.preventDefault();const buttons=[...form.querySelectorAll('button')];buttons.forEach(x=>x.disabled=true);try{await ensure();const fields=new FormData(form),email=fields.get('email').trim(),password=fields.get('password');if(event.submitter?.value==='register'){const businessName=fields.get('businessName').trim(),number=fields.get('number').trim();if(!businessName||!number)throw Error('מלא שם עסק ומספר עוסק בפרטי ההרשמה');if(!b.auth.currentUser||b.auth.currentUser.email!==email)await s.createUserWithEmailAndPassword(b.auth,email,password);const ref=s.doc(b.db,'customerAccounts',b.auth.currentUser.uid),old=await s.getDocFromServer(ref);if(!old.exists())await s.setDoc(ref,{uid:b.auth.currentUser.uid,email:b.auth.currentUser.email,businessName,number,status:'pending',expiresAt:0,createdAt:s.serverTimestamp()});}else await s.signInWithEmailAndPassword(b.auth,email,password);await refresh();await listen();if(live())dialog.close()}catch(e){error=message(e);paint()}finally{buttons.forEach(x=>x.disabled=false)}};
open.onclick=()=>{paint();dialog.showModal()};dialog.querySelector('.close').onclick=()=>dialog.close();dialog.querySelector('.refresh').onclick=()=>refresh();dialog.querySelector('.logout').onclick=async()=>{generation++;account=null;stop?.();if(b)await s.signOut(b.auth);paint()};dialog.querySelector('.reset').onclick=async()=>{try{await ensure();const email=form.elements.email.value.trim();if(!email)throw Error('הזן אימייל');await s.sendPasswordResetEmail(b.auth,email);status.textContent='אם החשבון קיים, יישלח מייל איפוס'}catch(e){status.textContent=message(e)}};
window.addEventListener('offline',()=>{generation++;account=null;paint()});window.addEventListener('online',async()=>{await refresh();await listen()});document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});setInterval(()=>{paint();if(navigator.onLine)refresh()},60000);paint();ensure().then(async()=>{await refresh();await listen()}).catch(e=>{error=message(e);paint()});return access;
}
